/** @module user-mfa-management */

import { getComponentStyles } from '@auth0/universal-components-core';
import * as React from 'react';

import { DeleteFactorConfirmation } from '@/components/auth0/my-account/shared/mfa/delete-factor-confirmation';
import { MFAEmptyState } from '@/components/auth0/my-account/shared/mfa/empty-state';
import { MFAErrorState } from '@/components/auth0/my-account/shared/mfa/error-state';
import { FactorsList } from '@/components/auth0/my-account/shared/mfa/factors-list';
import { UserMFASetupForm } from '@/components/auth0/my-account/shared/mfa/user-mfa-setup-form';
import { GateKeeper } from '@/components/auth0/shared/gate-keeper/gate-keeper';
import { StyledScope } from '@/components/auth0/shared/styled-scope';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardDescription, CardTitle } from '@/components/ui/card';
import { List, ListItem } from '@/components/ui/list';
import { useUserMFA } from '@/hooks/my-account/use-user-mfa';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import type { UserMFAMgmtProps, UserMFAMgmtViewProps } from '@/types/my-account/mfa/mfa-types';

/**
 * Multi-factor authentication management component.
 *
 * Complete MFA management interface for enrolling, viewing, and deleting authentication
 * factors. Supports TOTP authenticators, SMS, Email, Push notifications, and recovery codes.
 *
 * @param props - {@link UserMFAMgmtProps}
 * @param props.customMessages - Custom i18n message overrides
 * @param props.styling - CSS variables and class overrides
 * @param props.hideHeader - Hide the header section
 * @param props.showActiveOnly - Show only enrolled factors
 * @param props.disableEnroll - Disable enroll actions
 * @param props.disableDelete - Disable delete actions
 * @param props.readOnly - Render in read-only mode
 * @param props.factorConfig - Per-factor visibility/enabled configuration
 * @param props.onEnroll - Callback after successful enrollment
 * @param props.onDelete - Callback after successful deletion
 * @param props.onFetch - Callback after factors are loaded
 * @param props.onErrorAction - Callback when actions error
 * @param props.onBeforeAction - Callback before actions; return false to cancel
 * @param props.schema - Validation schema overrides
 * @returns MFA management component
 *
 * @see {@link UserMFAMgmtProps} for full props documentation
 *
 * @example
 * ```tsx
 * <UserMFAMgmt
 *   onEnroll={(factor) => console.log('Enrolled:', factor)}
 *   onDelete={(factor) => console.log('Deleted:', factor)}
 *   factorConfig={{
 *     otp: { enabled: true },
 *     sms: { enabled: true },
 *     email: { enabled: false },
 *   }}
 * />
 * ```
 */
function UserMFAMgmt({
  customMessages = {},
  styling = { variables: { common: {}, light: {}, dark: {} }, classes: {} },
  hideHeader = false,
  showActiveOnly = false,
  disableEnroll = false,
  disableDelete = false,
  readOnly = false,
  factorConfig = {},
  onEnroll,
  onDelete,
  onFetch,
  onErrorAction,
  onBeforeAction,
  schema,
}: UserMFAMgmtProps) {
  const {
    factorsByType,
    isLoadingFactors,
    isEnrolling,
    isDeleting,
    isConfirming,
    error,
    isEnrollDialogOpen,
    enrollFactor,
    enrollmentPhase,
    contact,
    otpData,
    recoveryCode,
    isDeleteDialogOpen,
    factorToDelete,
    visibleFactorTypes,
    hasNoActiveFactors,
    handleEnroll,
    handleCloseEnrollDialog,
    handleDeleteFactor,
    handleConfirmDelete,
    handleCancelDelete,
    handleSendCode,
    handleConfirmOtp,
    handleConfirmPush,
    handleConfirmRecoveryCode,
    handleEnterQRPhase,
  } = useUserMFA({
    showActiveOnly,
    readOnly,
    disableDelete,
    factorConfig,
    customMessages,
    onFetch,
    onEnroll,
    onDelete,
    onErrorAction,
    onBeforeAction,
  });

  return (
    <GateKeeper styling={styling} isLoading={isLoadingFactors}>
      <UserMFAMgmtView
        error={error}
        schema={schema}
        isEnrolling={isEnrolling}
        isDeleting={isDeleting}
        isConfirming={isConfirming}
        styling={styling}
        customMessages={customMessages}
        hideHeader={hideHeader}
        showActiveOnly={showActiveOnly}
        disableEnroll={disableEnroll}
        disableDelete={disableDelete}
        readOnly={readOnly}
        factorConfig={factorConfig}
        isEnrollDialogOpen={isEnrollDialogOpen}
        enrollFactor={enrollFactor}
        enrollmentPhase={enrollmentPhase}
        contact={contact}
        otpData={otpData}
        recoveryCode={recoveryCode}
        isDeleteDialogOpen={isDeleteDialogOpen}
        factorToDelete={factorToDelete}
        factorsByType={factorsByType}
        visibleFactorTypes={visibleFactorTypes}
        hasNoActiveFactors={hasNoActiveFactors}
        onEnrollFactor={handleEnroll}
        onDeleteFactor={handleDeleteFactor}
        onCloseEnrollDialog={handleCloseEnrollDialog}
        onConfirmDelete={handleConfirmDelete}
        onCancelDelete={handleCancelDelete}
        onSubmitContact={handleSendCode}
        onConfirmOtp={handleConfirmOtp}
        onContinueQR={handleConfirmPush}
        onConfirmRecoveryCode={handleConfirmRecoveryCode}
        onAdvanceToQR={handleEnterQRPhase}
      />
    </GateKeeper>
  );
}

/**
 * UserMFAMgmtView — Presentational component.
 * @param props - All state and handlers passed directly.
 * @returns User Management View element
 * @internal
 */
function UserMFAMgmtView({
  error,
  schema,
  isEnrolling,
  isDeleting,
  isConfirming,
  styling,
  customMessages,
  hideHeader,
  showActiveOnly,
  disableEnroll,
  disableDelete,
  readOnly,
  factorConfig,
  isEnrollDialogOpen,
  enrollFactor,
  enrollmentPhase,
  contact,
  otpData,
  recoveryCode,
  isDeleteDialogOpen,
  factorToDelete,
  factorsByType,
  visibleFactorTypes,
  hasNoActiveFactors,
  onEnrollFactor,
  onDeleteFactor,
  onCloseEnrollDialog,
  onConfirmDelete,
  onCancelDelete,
  onSubmitContact,
  onConfirmOtp,
  onContinueQR,
  onConfirmRecoveryCode,
  onAdvanceToQR,
}: UserMFAMgmtViewProps) {
  const { isDarkMode } = useTheme();
  const { t } = useTranslator('mfa', customMessages);
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  return (
    <StyledScope style={currentStyles.variables}>
      <Card className={cn('p-6', currentStyles.classes?.['UserMFAMgmt-card'])}>
        {error ? (
          <MFAErrorState
            title={t('component_error_title')}
            description={t('component_error_description')}
          />
        ) : (
          <>
            {!hideHeader && (
              <>
                <CardTitle
                  id="mfa-management-title"
                  className="text-2xl text-(length:--font-size-heading) font-medium text-left"
                >
                  {t('title')}
                </CardTitle>
                <CardDescription
                  id="mfa-management-desc"
                  className="text-sm text-(length:--font-size-paragraph) text-muted-foreground text-left"
                >
                  {t('description')}
                </CardDescription>
              </>
            )}
            {showActiveOnly && hasNoActiveFactors ? (
              <MFAEmptyState message={t('no_active_mfa')} />
            ) : (
              <List
                className="flex flex-col gap-0 w-full"
                aria-labelledby="mfa-management-title"
                aria-describedby="mfa-management-desc"
              >
                {visibleFactorTypes.map((factorType) => {
                  const factors = factorsByType[factorType] || [];
                  const activeFactors = factors.filter((f) => f.enrolled);
                  const isEnabledFactor = factorConfig?.[factorType]?.enabled !== false;
                  const hasActiveFactors = activeFactors.length > 0;

                  return (
                    <ListItem
                      key={factorType}
                      className={cn(
                        'w-full p-0 m-0 py-6 gap-3',
                        !isEnabledFactor && 'opacity-50 pointer-events-none',
                      )}
                      aria-disabled={!isEnabledFactor}
                      tabIndex={0}
                      aria-label={t(`${factorType}.title`)}
                    >
                      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-3">
                        <div className="flex flex-wrap items-center gap-2 sm:gap-3">
                          <span
                            className={cn(
                              'break-words text-card-foreground whitespace-normal text-base text-(length:--font-size-body) font-medium',
                            )}
                            id={`factor-title-${factorType}`}
                          >
                            {t(`${factorType}.title`)}
                          </span>

                          {hasActiveFactors && (
                            <Badge
                              variant="success"
                              size="sm"
                              className="shrink-0"
                              aria-label={t('enabled')}
                            >
                              {t('enabled')}
                            </Badge>
                          )}
                        </div>

                        {!readOnly && (
                          <Button
                            size="default"
                            variant="outline"
                            className="text-sm w-full sm:w-auto shrink-0"
                            onClick={() => onEnrollFactor(factorType)}
                            disabled={disableEnroll || !isEnabledFactor}
                            aria-label={t(`${factorType}.button-text`)}
                            aria-describedby={`factor-title-${factorType}`}
                          >
                            {t(`${factorType}.button-text`)}
                          </Button>
                        )}
                      </div>

                      {!hasActiveFactors && (
                        <p
                          className={cn(
                            'font-normal text-sm text-(length:--font-size-paragraph) text-muted-foreground text-left break-words',
                          )}
                          id={`factor-desc-${factorType}`}
                        >
                          {t(`${factorType}.description`)}
                        </p>
                      )}

                      {hasActiveFactors && (
                        <FactorsList
                          factors={activeFactors}
                          factorType={factorType}
                          readOnly={readOnly}
                          isEnabledFactor={isEnabledFactor}
                          onDeleteFactor={onDeleteFactor}
                          isDeletingFactor={isDeleting}
                          disableDelete={disableDelete}
                          styling={styling}
                          customMessages={customMessages}
                        />
                      )}
                    </ListItem>
                  );
                })}
              </List>
            )}
          </>
        )}
      </Card>
      {enrollFactor && (
        <UserMFASetupForm
          open={isEnrollDialogOpen}
          onClose={onCloseEnrollDialog}
          factorType={enrollFactor}
          enrollmentPhase={enrollmentPhase}
          contact={contact}
          otpData={otpData}
          recoveryCode={recoveryCode}
          isEnrolling={isEnrolling}
          isConfirming={isConfirming}
          onSubmitContact={onSubmitContact}
          onConfirmOtp={onConfirmOtp}
          onContinueQR={onContinueQR}
          onConfirmRecoveryCode={onConfirmRecoveryCode}
          onAdvanceToQR={onAdvanceToQR}
          schema={schema}
          styling={styling}
          customMessages={customMessages}
        />
      )}
      <DeleteFactorConfirmation
        open={isDeleteDialogOpen}
        onOpenChange={(open) => !open && !isDeleting && onCancelDelete()}
        factorToDelete={factorToDelete}
        isDeletingFactor={isDeleting}
        onConfirm={onConfirmDelete}
        onCancel={onCancelDelete}
        styling={styling}
        customMessages={customMessages}
      />
    </StyledScope>
  );
}

export { UserMFAMgmt, UserMFAMgmtView };

/**
 * MFA contact input form for email/SMS enrollment.
 * @module contact-input-form
 * @internal
 */

import {
  FACTOR_TYPE_EMAIL,
  createEmailContactSchema,
  createSmsContactSchema,
  type EmailContactForm,
  type SmsContactForm,
  getComponentStyles,
} from '@auth0/universal-components-core';
import { zodResolver } from '@hookform/resolvers/zod';
import { MailIcon, SmartphoneIcon } from 'lucide-react';
import * as React from 'react';
import { useForm } from 'react-hook-form';

import { OTPVerificationForm } from '@/components/auth0/my-account/shared/mfa/otp-verification-form';
import { Button } from '@/components/ui/button';
import {
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormMessage,
} from '@/components/ui/form';
import { Spinner } from '@/components/ui/spinner';
import { TextField } from '@/components/ui/text-field';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { FORM_REVALIDATE_MODE, FORM_VALIDATION_MODE } from '@/lib/constants/form-constants';
import { ENTER_CONTACT, ENTER_OTP } from '@/lib/constants/my-account/mfa/mfa-constants';
import type { ContactInputFormProps } from '@/types/my-account/mfa/mfa-types';

type ContactForm = EmailContactForm | SmsContactForm;

type Phase = typeof ENTER_CONTACT | typeof ENTER_OTP;

/**
 *
 * @param props - Component props.
 * @param props.factorType - The MFA factor type
 * @param props.contact - Current contact value (email or phone) from hook state
 * @param props.isEnrolling - Whether enrollment is in progress
 * @param props.isConfirming - Whether OTP confirmation is in progress
 * @param props.onSubmitContact - Called with contact options; returns true on success
 * @param props.onConfirmOtp - Called with the 6-digit OTP code
 * @param props.onClose - Callback fired when the component should close
 * @param props.schema - Zod validation schema
 * @param props.styling - Custom styling configuration with variables and classes
 * @param props.customMessages - Custom translation messages to override defaults
 * @returns JSX element
 */
export function ContactInputForm({
  factorType,
  contact,
  isEnrolling,
  isConfirming,
  onSubmitContact,
  onConfirmOtp,
  onClose,
  schema,
  styling = {
    variables: {
      common: {},
      light: {},
      dark: {},
    },
    classes: {},
  },
  customMessages = {},
}: ContactInputFormProps) {
  const [phase, setPhase] = React.useState<Phase>(ENTER_CONTACT);
  const { t } = useTranslator('mfa', customMessages);
  const { isDarkMode } = useTheme();
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  const ContactSchema = React.useMemo(() => {
    return factorType === FACTOR_TYPE_EMAIL
      ? createEmailContactSchema(t('errors.invalid_email'), schema?.email)
      : createSmsContactSchema(t('errors.invalid_phone_number'), schema?.phone);
  }, [factorType, t, schema]);

  const form = useForm<ContactForm>({
    resolver: zodResolver(ContactSchema),
    mode: FORM_VALIDATION_MODE,
    reValidateMode: FORM_REVALIDATE_MODE,
    defaultValues: { contact: contact || '' },
  });

  const handleCancel = () => {
    form.reset();
    onClose?.();
  };

  const handleBack = () => setPhase(ENTER_CONTACT);

  const handleSubmit = async (data: ContactForm) => {
    const options: Record<string, string> =
      factorType === FACTOR_TYPE_EMAIL ? { email: data.contact } : { phone_number: data.contact };
    const success = await onSubmitContact(options);
    if (success) setPhase(ENTER_OTP);
  };

  const renderContactScreen = () => (
    <div style={currentStyles.variables} className="w-full max-w-sm mx-auto">
      <div className="flex flex-col items-center justify-center flex-1 space-y-10">
        {isEnrolling ? (
          <div
            className="absolute inset-0 flex items-center justify-center"
            role="status"
            aria-live="polite"
          >
            <Spinner aria-label={t('loading')} />
          </div>
        ) : (
          <>
            <p
              className="text-center text-primary text-sm text-(length:--font-size-paragraph) font-normal"
              id="contact-description"
            >
              {factorType === FACTOR_TYPE_EMAIL
                ? t('enrollment_form.enroll_email_description')
                : t('enrollment_form.enroll_sms_description')}
            </p>

            <div className="w-full">
              <Form {...form}>
                <form
                  onSubmit={form.handleSubmit(handleSubmit)}
                  className="space-y-6"
                  aria-describedby="contact-description"
                >
                  <FormField
                    control={form.control}
                    name="contact"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel
                          className="text-left text-sm text-(length:--font-size-paragraph) font-medium"
                          htmlFor="contact-input"
                        >
                          {factorType === FACTOR_TYPE_EMAIL
                            ? t('enrollment_form.email_address')
                            : t('enrollment_form.phone_number')}
                        </FormLabel>
                        <FormControl>
                          <TextField
                            id="contact-input"
                            type={factorType === FACTOR_TYPE_EMAIL ? 'email' : 'tel'}
                            autoComplete={factorType === FACTOR_TYPE_EMAIL ? 'email' : 'tel'}
                            startAdornment={
                              <div className="p-1.5" aria-hidden="true">
                                {factorType === FACTOR_TYPE_EMAIL ? (
                                  <MailIcon />
                                ) : (
                                  <SmartphoneIcon />
                                )}
                              </div>
                            }
                            placeholder={
                              factorType === FACTOR_TYPE_EMAIL
                                ? t('enrollment_form.enroll_email_placeholder')
                                : t('enrollment_form.enroll_sms_placeholder')
                            }
                            error={Boolean(form.formState.errors.contact)}
                            aria-invalid={Boolean(form.formState.errors.contact)}
                            {...field}
                          />
                        </FormControl>
                        <FormMessage
                          className="text-left text-sm text-(length:--font-size-paragraph)"
                          id="contact-error"
                          role="alert"
                        />
                      </FormItem>
                    )}
                  />
                  <div className="flex flex-row justify-end gap-3 mt-6 mb-6">
                    <Button
                      type="button"
                      className="text-sm"
                      variant="outline"
                      size="default"
                      onClick={handleCancel}
                      aria-label={t('cancel')}
                    >
                      {t('cancel')}
                    </Button>
                    <Button
                      type="submit"
                      size="default"
                      className="text-sm"
                      disabled={!form.formState.isValid || isEnrolling}
                      aria-label={t('submit')}
                    >
                      {t('submit')}
                    </Button>
                  </div>
                </form>
              </Form>
            </div>
          </>
        )}
      </div>
    </div>
  );

  const renderOtpScreen = () => (
    <OTPVerificationForm
      factorType={factorType}
      contact={contact}
      isConfirming={isConfirming}
      onConfirmOtp={onConfirmOtp}
      onBack={handleBack}
      styling={styling}
      customMessages={customMessages}
    />
  );

  return phase === ENTER_CONTACT ? renderContactScreen() : renderOtpScreen();
}

/**
 * MFA factor deletion confirmation dialog.
 * @module delete-factor-confirmation
 * @internal
 */

import { getComponentStyles } from '@auth0/universal-components-core';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Separator } from '@/components/ui/separator';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import type { DeleteFactorConfirmationProps } from '@/types/my-account/mfa/mfa-types';

/**
 *
 * @param props - Component props.
 * @param props.open - Whether the component is open/visible
 * @param props.onOpenChange - Callback fired when open state changes
 * @param props.factorToDelete - The factor selected for deletion
 * @param props.isDeletingFactor - Whether a factor deletion is in progress
 * @param props.onConfirm - Callback fired when the action is confirmed
 * @param props.onCancel - Callback fired when the operation is cancelled
 * @param props.styling - Custom styling configuration with variables and classes
 * @param props.customMessages - Custom translation messages to override defaults
 * @returns JSX element
 */
export function DeleteFactorConfirmation({
  open,
  onOpenChange,
  factorToDelete,
  isDeletingFactor,
  onConfirm,
  onCancel,
  styling = {
    variables: {
      common: {},
      light: {},
      dark: {},
    },
    classes: {},
  },
  customMessages = {},
}: DeleteFactorConfirmationProps) {
  const { t } = useTranslator('mfa', customMessages);
  const { isDarkMode } = useTheme();
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        style={currentStyles?.variables}
        className={cn(
          'w-[600px] max-h-[90vh]',
          currentStyles.classes?.['DeleteFactorConfirmation-dialogContent'],
        )}
      >
        <DialogHeader>
          <DialogTitle className="text-center text-(length:--font-size-title) font-medium">
            {t('delete_mfa_title')}
          </DialogTitle>
          <Separator className="my-2" />
        </DialogHeader>

        <div className="flex flex-col items-center mt-6">
          <p
            className={cn(
              'text-center text-(length:--font-size-paragraph) font-normal mb-10 text-primary',
            )}
          >
            {t(`delete_mfa_${factorToDelete?.type}_consent`)}
          </p>

          <div className="flex flex-row justify-end gap-3 w-full mt-6 mb-6">
            <Button
              variant="outline"
              size="default"
              className="text-sm"
              onClick={onCancel}
              disabled={isDeletingFactor}
              aria-label={t('cancel')}
            >
              {t('cancel')}
            </Button>
            <Button
              variant="destructive"
              size="default"
              className="text-sm"
              onClick={() => onConfirm()}
              disabled={isDeletingFactor}
              aria-label={t('confirm')}
            >
              {isDeletingFactor ? t('deleting') : t('confirm')}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * MFA empty state display.
 * @module empty-state
 * @internal
 */

import { cn } from '@/lib/utils';

interface MFAEmptyStateProps {
  message: string;
  className?: string;
}

/**
 *
 * @param props - Component props.
 * @param props.message - The message to display
 * @param props.className - Optional CSS class name for styling
 * @returns JSX element
 */
export function MFAEmptyState({ message, className }: MFAEmptyStateProps) {
  return (
    <p
      className={cn(
        'text-sm text-(length:--font-size-paragraph) text-center text-muted-foreground',
        className,
      )}
    >
      {message}
    </p>
  );
}

/**
 * MFA error state display.
 * @module error-state
 * @internal
 */

import { cn } from '@/lib/utils';

interface ErrorStateProps {
  title: string;
  description: string;
  className?: string;
}

/**
 * Displays an error state for MFA operations.
 *
 * @param props - Component props.
 * @param props.title - Error title text.
 * @param props.description - Error description text.
 * @param props.className - Additional CSS class names.
 * @returns Error state component.
 * @internal
 */
export function MFAErrorState({ title, description, className }: ErrorStateProps) {
  return (
    <div
      className={cn('flex flex-col items-center justify-center p-4 space-y-2', className)}
      role="alert"
      aria-live="assertive"
    >
      <h1
        className="text-base font-medium text-center text-destructive-foreground"
        id="mfa-error-title"
      >
        {title}
      </h1>
      <p className="text-sm text-center text-destructive-foreground whitespace-pre-line">
        {description}
      </p>
    </div>
  );
}

/**
 * MFA enrolled factors list display.
 * @module factors-list
 * @internal
 */

import { FACTOR_TYPE_PHONE, FACTOR_TYPE_EMAIL } from '@auth0/universal-components-core';
import { getComponentStyles } from '@auth0/universal-components-core';
import { MoreVertical, Trash2, Mail, Smartphone } from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Popover, PopoverTrigger, PopoverContent } from '@/components/ui/popover';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import type { FactorsListProps } from '@/types/my-account/mfa/mfa-types';

const FACTOR_ICONS = {
  [FACTOR_TYPE_PHONE]: Smartphone,
  [FACTOR_TYPE_EMAIL]: Mail,
} as const;

/**
 *
 * @param props - Component props.
 * @param props.factors - Array of MFA factors
 * @param props.factorType - The MFA factor type
 * @param props.readOnly - Whether the component is in read-only mode
 * @param props.isEnabledFactor - Whether the factor is enabled
 * @param props.onDeleteFactor - Callback to delete a factor
 * @param props.isDeletingFactor - Whether a factor deletion is in progress
 * @param props.disableDelete - Whether delete action is disabled
 * @param props.styling - Custom styling configuration with variables and classes
 * @param props.customMessages - Custom translation messages to override defaults
