/**
 * Loading spinner component.
 * @module spinner
 * @internal
 */

import type { VariantProps } from 'class-variance-authority';
import { cva } from 'class-variance-authority';
import * as React from 'react';

import { cn } from '@/lib/utils';

const spinnerVariants = cva(
  'inline-block h-8 w-8 animate-spin rounded-full border-2 border-transparent',
  {
    variants: {
      variant: {
        solid: '!border-t-current',
        dots: 'animate-[spin_5s_linear_infinite] border-6 border-dotted border-current',
        pulse: 'animate-pulse bg-current',
      },
      size: {
        sm: 'size-4',
        md: 'size-8',
        lg: 'size-12',
      },
      colorScheme: {
        primary: 'text-primary',
        foreground: 'text-primary-foreground',
        muted: 'text-muted-foreground',
      },
    },
    defaultVariants: {
      variant: 'solid',
      size: 'md',
      colorScheme: 'primary',
    },
  },
);

export interface SpinnerProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof spinnerVariants> {}

export function Spinner({ variant, size, colorScheme, className, ...props }: SpinnerProps) {
  return (
    <div className={cn(spinnerVariants({ variant, size, colorScheme }), className)} {...props}>
      <span className="sr-only">Loading...</span>
    </div>
  );
}

/**
 * Text input field with variants.
 * @module text-field
 * @internal
 */

import type { VariantProps } from 'class-variance-authority';
import { cva } from 'class-variance-authority';
import * as React from 'react';

import { cn } from '@/lib/utils';

const textFieldVariants = cva(
  "bg-input aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive relative box-border inline-flex w-full shrink-0 cursor-text items-center justify-center gap-2 overflow-hidden rounded-2xl text-sm transition-[color,box-shadow] duration-150 ease-in-out outline-none disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default:
          'border-border/50 text-input-foreground shadow-input-resting hover:shadow-input-hover hover:border-primary/25 focus-within:border-border focus-within:ring-primary/15 focus-within:ring-4',
        error:
          'border-destructive-border/50 text-destructive-foreground shadow-input-destructive-resting hover:shadow-input-destructive-hover hover:border-destructive-border/25 focus-within:ring-destructive-border/15 focus-within:ring-4',
      },
      size: {
        default: 'h-10',
        sm: 'h-9',
        lg: 'h-11',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

export interface TextFieldProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'> {
  error?: boolean;
  helperText?: string;
  size?: VariantProps<typeof textFieldVariants>['size'];
  variant?: VariantProps<typeof textFieldVariants>['variant'];
  startAdornment?: React.ReactNode;
  endAdornment?: React.ReactNode;
}

const TextField = React.forwardRef<HTMLInputElement, TextFieldProps>(
  (
    { className, variant, size, error, helperText, startAdornment, endAdornment, ...props },
    ref,
  ) => {
    const isDisabled = props.disabled;

    const WrapperComponent = props.id ? 'div' : 'label';

    return (
      <div className="flex w-full flex-col">
        <WrapperComponent
          className={cn(
            textFieldVariants({ variant: error ? 'error' : variant, size }),
            'group items-center gap-0.5',
            isDisabled &&
              'bg-input-muted text-input-muted-foreground cursor-not-allowed opacity-50',
            isDisabled && variant === 'default' && 'bg-input-muted',
            startAdornment && 'pl-[5px]',
            endAdornment && 'pr-[5px]',
            className,
          )}
        >
          {startAdornment && (
            <div className="[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4">
              {startAdornment}
            </div>
          )}
          <input
            className={cn(
              'w-full flex-1 bg-transparent px-3 py-2 outline-none file:border-0 file:bg-transparent file:text-sm file:font-medium',
              isDisabled &&
                'bg-input-muted text-input-muted-foreground cursor-not-allowed opacity-50',
              startAdornment && 'pl-0',
              endAdornment && 'pr-0',
              size === 'default' && 'h-10',
              size === 'sm' && 'h-9',
              size === 'lg' && 'h-11',
            )}
            ref={ref}
            {...props}
          />
          {endAdornment && (
            <div className="[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4">
              {endAdornment}
            </div>
          )}
        </WrapperComponent>
        {helperText && (
          <p
            className={cn(
              'mt-1.5 px-2 text-xs',
              error ? 'text-destructive-foreground' : 'text-muted-foreground',
            )}
          >
            {helperText}
          </p>
        )}
      </div>
    );
  },
);

TextField.displayName = 'TextField';

export { TextField, textFieldVariants };

/**
 * Tooltip using Radix primitives.
 * @module tooltip
 * @internal
 */

'use client';

import * as TooltipPrimitive from '@radix-ui/react-tooltip';
import { cva, type VariantProps } from 'class-variance-authority';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { usePortalContainer } from '@/providers/portal-context';

const tooltipVariants = cva(
  'bg-popover text-popover-foreground data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 shadow-bevel-lg z-50 w-fit rounded-xl px-2 py-1 text-sm text-balance',
  {
    variants: {
      position: {
        top: 'origin-bottom',
        bottom: 'origin-top',
        left: 'origin-left',
        right: 'origin-right',
      },
    },
    defaultVariants: {
      position: 'top',
    },
  },
);

function Tooltip({ children, ...props }: React.ComponentProps<typeof TooltipPrimitive.Root>) {
  return (
    <TooltipPrimitive.Provider>
      <TooltipPrimitive.Root {...props}>{children}</TooltipPrimitive.Root>
    </TooltipPrimitive.Provider>
  );
}

function TooltipTrigger({
  asChild = true,
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Trigger>) {
  return <TooltipPrimitive.Trigger asChild={asChild} {...props} />;
}

interface TooltipContentProps
  extends React.ComponentProps<typeof TooltipPrimitive.Content>,
    VariantProps<typeof tooltipVariants> {}

const TooltipContent = React.forwardRef<
  React.ElementRef<typeof TooltipPrimitive.Content>,
  TooltipContentProps
>(({ className, side = 'top', position, sideOffset = 8, children, ...props }, ref) => {
  const portalContainer = usePortalContainer();
  return (
    <TooltipPrimitive.Portal container={portalContainer}>
      <TooltipPrimitive.Content
        ref={ref}
        side={side}
        sideOffset={sideOffset}
        className={cn(tooltipVariants({ position: position || side }), className)}
        {...props}
      >
        {children}
        <TooltipPrimitive.Arrow className="fill-popover" />
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
});
TooltipContent.displayName = TooltipPrimitive.Content.displayName;

export { Tooltip, TooltipTrigger, TooltipContent, tooltipVariants };

/**
 * MFA service hook with TanStack Query.
 * @module use-user-mfa-service
 * @internal
 */

import {
  MFAMappers,
  mfaQueryKeys,
  type Authenticator,
  type MFAType,
  type EnrollOptions,
  type ConfirmEnrollmentOptions,
} from '@auth0/universal-components-core';
import { useQuery, useMutation } from '@tanstack/react-query';

import { useCoreClient } from '@/hooks/shared/use-core-client';
import type { UseUserMFAServiceReturn } from '@/types/my-account/mfa/mfa-types';

/**
 * Internal service hook for MFA operations backed by TanStack Query.
 * Provides queries and mutations; use `useUserMFA` for the public API.
 * @param onlyActive - Whether to return only active factors.
 * @returns MFA query and mutation handlers for factor listing and enrollment lifecycle operations.
 * @internal
 */
export function useUserMFAService(onlyActive: boolean): UseUserMFAServiceReturn {
  const { coreClient } = useCoreClient();

  const factorsQuery = useQuery<Record<MFAType, Authenticator[]>>({
    queryKey: mfaQueryKeys.factors(onlyActive),
    queryFn: async () => {
      const client = coreClient!.getMyAccountApiClient();
      const [availableFactors, enrolledFactors] = await Promise.all([
        client.factors.list(),
        client.authenticationMethods.list(),
      ]);
      return MFAMappers.fromAPI(availableFactors, enrolledFactors, onlyActive) as Record<
        MFAType,
        Authenticator[]
      >;
    },
    enabled: !!coreClient,
  });

  const enrollMutation = useMutation({
    mutationFn: ({
      factorType,
      options = {},
    }: {
      factorType: MFAType;
      options?: EnrollOptions;
    }) => {
      const client = coreClient!.getMyAccountApiClient();
      const params = MFAMappers.buildEnrollParams(factorType, options);
      return client.authenticationMethods.create(params);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (authenticatorId: string) =>
      coreClient!.getMyAccountApiClient().authenticationMethods.delete(authenticatorId),
  });

  const verifyMutation = useMutation({
    mutationFn: ({
      factorType,
      authSession,
      authenticationMethodId,
      options,
    }: {
      factorType: MFAType;
      authSession: string;
      authenticationMethodId: string;
      options: ConfirmEnrollmentOptions;
    }) => {
      const client = coreClient!.getMyAccountApiClient();
      const params = MFAMappers.buildConfirmEnrollmentParams(factorType, authSession, options);
      return client.authenticationMethods.verify(authenticationMethodId, params);
    },
  });

  return {
    factorsQuery,
    enrollMutation,
    deleteMutation,
    verifyMutation,
  };
}

/**
 * User MFA management hook.
 * @module use-user-mfa
 */

import {
  FACTOR_TYPE_EMAIL,
  FACTOR_TYPE_PHONE,
  FACTOR_TYPE_PUSH_NOTIFICATION,
  FACTOR_TYPE_RECOVERY_CODE,
  isNotifiableError,
  normalizeError,
  type Authenticator,
  type CreateAuthenticationMethodResponseContent,
  type MFAType,
} from '@auth0/universal-components-core';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { toast } from 'sonner';

import { useUserMFAService } from '@/hooks/my-account/shared/services/use-user-mfa-service';
import { useErrorHandler } from '@/hooks/shared/use-error-handler';
import { useTranslator } from '@/hooks/shared/use-translator';
import {
  CONFIRM,
  ENTER_CONTACT,
  ENTER_QR,
  ENROLL,
  QR_PHASE_INSTALLATION,
  SHOW_RECOVERY_CODE,
} from '@/lib/constants/my-account/mfa/mfa-constants';
import type {
  EnrollmentPhase,
  UserMFAOptions,
  UseUserMFAReturn,
} from '@/types/my-account/mfa/mfa-types';

const EMPTY_SESSION = { authSession: '', authenticationMethodId: '' };

const extractSession = (res: CreateAuthenticationMethodResponseContent) => ({
  authSession: res.auth_session,
  authenticationMethodId: 'id' in res ? res.id : '',
});

const extractOtpData = (res: CreateAuthenticationMethodResponseContent) => ({
  barcodeUri: 'barcode_uri' in res ? res.barcode_uri : '',
  manualInputCode: 'manual_input_code' in res ? (res.manual_input_code ?? '') : '',
});

/**
 * Hook for user MFA management — fetch, enroll, delete, confirm, and all UI state.
 * @param options - Hook options.
 * @returns MFA state, UI handlers, and API methods.
 */
export function useUserMFA({
  showActiveOnly = false,
  readOnly = false,
  disableDelete = false,
  factorConfig,
  customMessages = {},
  onFetch,
  onEnroll,
  onDelete,
  onErrorAction,
  onBeforeAction,
}: UserMFAOptions = {}): UseUserMFAReturn {
  const { t } = useTranslator('mfa', customMessages);
  const handleError = useErrorHandler();
  const { factorsQuery, enrollMutation, deleteMutation, verifyMutation } =
    useUserMFAService(showActiveOnly);

  const [isEnrollDialogOpen, setIsEnrollDialogOpen] = useState(false);
  const [enrollFactor, setEnrollFactor] = useState<MFAType | null>(null);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [factorToDelete, setFactorToDelete] = useState<{ id: string; type: MFAType } | null>(null);

  const [enrollmentPhase, setEnrollmentPhase] = useState<EnrollmentPhase>(null);
  const [enrollmentSession, setEnrollmentSession] = useState(EMPTY_SESSION);
  const [contact, setContact] = useState('');
  const [otpData, setOtpData] = useState({ barcodeUri: '', manualInputCode: '' });
  const [recoveryCode, setRecoveryCode] = useState('');

  const factorsByType = factorsQuery.data ?? ({} as Record<MFAType, Authenticator[]>);

  useEffect(() => {
    if (factorsQuery.isSuccess) onFetch?.();
  }, [factorsQuery.isSuccess, onFetch]);

  useEffect(() => {
    if (factorsQuery.isError) {
      handleError(factorsQuery.error, { fallbackMessage: t('errors.factors_loading_error') });
    }
  }, [factorsQuery.isError, factorsQuery.error, handleError, t]);

  const visibleFactorTypes = useMemo(
    () =>
      (Object.keys(factorsByType) as MFAType[]).filter(
        (factorType) => factorConfig?.[factorType]?.visible !== false,
      ),
    [factorsByType, factorConfig],
  );

  const hasNoActiveFactors = useMemo(
    () => visibleFactorTypes.every((type) => !factorsByType[type]?.some((f) => f.enrolled)),
    [visibleFactorTypes, factorsByType],
  );

  const handleEnrollError = useCallback(
    (err: unknown, stage: typeof ENROLL | typeof CONFIRM, factor: MFAType | null) => {
      if (!isNotifiableError(err)) {
        handleError(err);
        return;
      }
      const label = stage === ENROLL ? t('enrollment') : t('confirmation');
      const error = normalizeError(err, {
        resolver: (code) => t(`errors.${factor}.${code}`, {}, t('errors.unexpected')),
      });
      toast.error(`${label} ${t('errors.failed', { message: error.message })}`);
      onErrorAction?.(error, stage);
    },
    [handleError, onErrorAction, t],
  );

  const handleEnrollSuccess = useCallback(async () => {
    toast.success(t('enroll_factor'), {
      duration: 2000,
      onAutoClose: () => onEnroll?.(),
    });
    setIsEnrollDialogOpen(false);
    setEnrollFactor(null);
    setEnrollmentPhase(null);
    setEnrollmentSession(EMPTY_SESSION);
    setContact('');
    setOtpData({ barcodeUri: '', manualInputCode: '' });
    setRecoveryCode('');
    await factorsQuery.refetch();
  }, [factorsQuery, onEnroll, t]);

  const verifyAndComplete = useCallback(
    async (params: Parameters<typeof verifyMutation.mutateAsync>[0]) => {
      try {
        await verifyMutation.mutateAsync(params);
        await handleEnrollSuccess();
      } catch (err) {
        handleEnrollError(err, CONFIRM, params.factorType);
      }
    },
    [verifyMutation, handleEnrollSuccess, handleEnrollError],
  );

  const handleEnroll = useCallback(
    async (factor: MFAType) => {
      setEnrollFactor(factor);
      setIsEnrollDialogOpen(true);

      if (factor === FACTOR_TYPE_EMAIL || factor === FACTOR_TYPE_PHONE) {
        setEnrollmentPhase(ENTER_CONTACT);
        return;
      }

      if (factor === FACTOR_TYPE_PUSH_NOTIFICATION) {
        setEnrollmentPhase(QR_PHASE_INSTALLATION);
        return;
      }

      try {
        const enrollment = await enrollMutation.mutateAsync({ factorType: factor, options: {} });
        setEnrollmentSession(extractSession(enrollment));
        if (factor === FACTOR_TYPE_RECOVERY_CODE) {
          setRecoveryCode('recovery_code' in enrollment ? enrollment.recovery_code : '');
          setEnrollmentPhase(SHOW_RECOVERY_CODE);
        } else {
          setOtpData(extractOtpData(enrollment));
          setEnrollmentPhase(ENTER_QR);
        }
      } catch (err) {
        handleEnrollError(err, ENROLL, factor);
        setIsEnrollDialogOpen(false);
        setEnrollFactor(null);
      }
    },
    [enrollMutation, handleEnrollError],
  );

  const handleCancelDelete = useCallback(() => {
    if (deleteMutation.isPending) return;
    setIsDeleteDialogOpen(false);
    setFactorToDelete(null);
  }, [deleteMutation.isPending]);

  const handleCloseEnrollDialog = useCallback(async () => {
    setIsEnrollDialogOpen(false);
    setEnrollmentPhase(null);
    setEnrollmentSession(EMPTY_SESSION);
    setContact('');
    setOtpData({ barcodeUri: '', manualInputCode: '' });
    setRecoveryCode('');
    if (enrollFactor === FACTOR_TYPE_PUSH_NOTIFICATION && enrollmentSession.authSession) {
      await factorsQuery.refetch();
    }
    setEnrollFactor(null);
  }, [enrollFactor, enrollmentSession.authSession, factorsQuery]);

  const executeDelete = useCallback(
    async (factorId: string) => {
      try {
        await deleteMutation.mutateAsync(factorId);
        await factorsQuery.refetch();
        toast.success(t('remove_factor'), {
          duration: 2000,
          onAutoClose: () => onDelete?.(),
        });
      } catch (err) {
        if (isNotifiableError(err)) {
          onErrorAction?.(
            err instanceof Error ? err : new Error(t('errors.delete_factor')),
            'delete',
          );
        }
        handleError(err, { fallbackMessage: t('errors.delete_factor') });
      } finally {
        setIsDeleteDialogOpen(false);
        setFactorToDelete(null);
      }
    },
    [deleteMutation, factorsQuery, handleError, onDelete, onErrorAction, t],
  );

  const handleConfirmDelete = useCallback(async () => {
    if (!factorToDelete) return;
    await executeDelete(factorToDelete.id);
  }, [factorToDelete, executeDelete]);

  const handleDeleteFactor = useCallback(
    async (factorId: string, factorType: MFAType) => {
      if (readOnly || disableDelete) return;
      if (onBeforeAction) {
        const canProceed = await onBeforeAction('delete', factorType);
        if (!canProceed) return;
        await executeDelete(factorId);
      } else {
        setFactorToDelete({ id: factorId, type: factorType });
        setIsDeleteDialogOpen(true);
      }
    },
    [readOnly, disableDelete, onBeforeAction, executeDelete],
  );

  const handleSendCode = useCallback(
    async (options: Record<string, string>): Promise<boolean> => {
      try {
        const enrollment = await enrollMutation.mutateAsync({ factorType: enrollFactor!, options });
        setContact(options.email ?? options.phone_number ?? '');
        setEnrollmentSession(extractSession(enrollment));
        return true;
      } catch (err) {
        handleEnrollError(err, ENROLL, enrollFactor);
        return false;
      }
    },
    [enrollFactor, enrollMutation, handleEnrollError],
  );

  const handleConfirmOtp = useCallback(
    (otpCode: string) =>
      verifyAndComplete({
        factorType: enrollFactor!,
        authSession: enrollmentSession.authSession,
        authenticationMethodId: enrollmentSession.authenticationMethodId,
        options: { userOtpCode: otpCode },
      }),
    [enrollFactor, enrollmentSession, verifyAndComplete],
  );

  const handleEnterQRPhase = useCallback(async () => {
    if (!enrollFactor) return;
    try {
      const enrollment = await enrollMutation.mutateAsync({
        factorType: enrollFactor,
        options: {},
      });
      setEnrollmentSession(extractSession(enrollment));
      setOtpData(extractOtpData(enrollment));
      setEnrollmentPhase(ENTER_QR);
    } catch (err) {
      handleEnrollError(err, ENROLL, enrollFactor);
      setIsEnrollDialogOpen(false);
      setEnrollFactor(null);
    }
  }, [enrollFactor, enrollMutation, handleEnrollError]);

  const handleConfirmPush = useCallback(async () => {
    if (enrollFactor !== FACTOR_TYPE_PUSH_NOTIFICATION) return;
    await verifyAndComplete({
      factorType: enrollFactor,
      authSession: enrollmentSession.authSession,
      authenticationMethodId: enrollmentSession.authenticationMethodId,
      options: {},
    });
  }, [enrollFactor, enrollmentSession, verifyAndComplete]);

  const handleConfirmRecoveryCode = useCallback(
    () =>
      verifyAndComplete({
        factorType: enrollFactor!,
        authSession: enrollmentSession.authSession,
        authenticationMethodId: enrollmentSession.authenticationMethodId,
        options: {},
      }),
    [enrollFactor, enrollmentSession, verifyAndComplete],
  );

  return {
    factorsByType,
    isLoadingFactors: factorsQuery.isLoading,
    isEnrolling: enrollMutation.isPending,
    isDeleting: deleteMutation.isPending,
    isConfirming: verifyMutation.isPending,
    error: factorsQuery.isError ? t('errors.factors_loading_error') : null,
    isEnrollDialogOpen,
    enrollFactor,
    enrollmentPhase,
    isDeleteDialogOpen,
    factorToDelete,
    visibleFactorTypes,
    hasNoActiveFactors,
    contact,
    otpData,
    recoveryCode,
    handleCancelDelete,
    handleConfirmDelete,
    handleEnroll,
    handleCloseEnrollDialog,
    handleDeleteFactor,
    handleSendCode,
    handleConfirmOtp,
    handleConfirmPush,
    handleConfirmRecoveryCode,
    handleEnterQRPhase,
  };
}

/**
 * CoreClient initialization hook.
 * @module use-core-client-initialization
 * @internal
 */

import type {
  CoreClientInterface,
  AuthDetails,
  I18nInitOptions,
} from '@auth0/universal-components-core';
import { createCoreClient } from '@auth0/universal-components-core';
import * as React from 'react';

interface UseCoreClientInitializationProps {
  authDetails: AuthDetails;
  i18nOptions?: I18nInitOptions;
}

/**
 * @internal
 * @param props - Initialization props.
 * @returns The initialized CoreClient instance, or null while initializing.
 */
export const useCoreClientInitialization = ({
  authDetails,
  i18nOptions,
}: UseCoreClientInitializationProps): CoreClientInterface | null => {
  const { authProxyUrl } = authDetails;
  const [coreClient, setCoreClient] = React.useState<CoreClientInterface | null>(null);

  React.useEffect(() => {
    const initializeCoreClient = async () => {
      try {
        const initializedCoreClient = await createCoreClient(authDetails, i18nOptions);
        setCoreClient(initializedCoreClient);
      } catch (error) {
        console.error(error);
      }
    };
    initializeCoreClient();
  }, [authProxyUrl, i18nOptions]);

  return coreClient;
};

/**
 * CoreClient context and hook.
 * @module use-core-client
 */

import type { CoreClientInterface } from '@auth0/universal-components-core';
import * as React from 'react';

/** @internal */
const CoreClientContext = React.createContext<{
  coreClient: CoreClientInterface | null;
}>({
  coreClient: null,
});

/**
 * Hook to access CoreClient from context.
 * @returns CoreClient instance or null.
 * @throws If used outside Auth0ComponentProvider.
 */
export const useCoreClient = () => {
  const context = React.useContext(CoreClientContext);
  if (!context) {
    throw new Error('useCoreClient must be used within Auth0ComponentProvider');
  }
  return context;
};

export { CoreClientContext };

/**
 * Error handling hook with toast error.
 * @module use-error-handler
 */

import {
  isNetworkError,
  isNotifiableError,
  resolveErrorMessage,
  getStatusCode,
  hasApiErrorBody,
  ERROR_CODES,
} from '@auth0/universal-components-core';
import { useCallback } from 'react';

import { showToast } from '@/components/auth0/shared/toast';
import { useTranslator } from '@/hooks/shared/use-translator';

interface ErrorHandlerCallOptions {
  fallbackMessage?: string;
}

/**
 * Hook for consistent error handling across the app.
 *
 * @returns Error handler function.
 *
 * @example
 * const handleError = useErrorHandler();
 *
 * // With custom message
 * onError: (error) => handleError(error, {
 *   fallbackMessage: t('my_error')
 * });
 *
 * // With defaults
 * onError: handleError;
 */
export function useErrorHandler() {
  const { t } = useTranslator('common');

  return useCallback(
    (error: unknown, options: ErrorHandlerCallOptions = {}): void => {
      if (!isNotifiableError(error)) return;

      const getCustomErrorMessage = (err: unknown): string | undefined => {
        if (isNetworkError(err)) return t('error.network');
        const status = getStatusCode(err);
        switch (status) {
          case 400:
            return t('error.bad_request');
          case 401:
            return t('error.missing_token');
          case 403:
            return hasApiErrorBody(err) && err.body?.type?.includes(ERROR_CODES.INSUFFICIENT_SCOPE)
              ? t('error.insufficient_scope')
              : t('error.forbidden');
          case 404:
            return t('error.not_found');
          case 429:
            return t('error.rate_limit');
          default:
            return undefined;
        }
      };

      showToast({
        type: 'error',
        message:
          getCustomErrorMessage(error) ??
          resolveErrorMessage(error, options.fallbackMessage ?? t('error.generic')),
      });
    },
    [t],
  );
}

